steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
    {
      issue(identifier: \"MOB-42\") {
        id
        identifier
        title
        priority
        subIssues(first: 50) {
          nodes {
            id
            identifier
            title
            estimate
            dueDate
            priority
          }
        }
      }
    }"
  }'
